#!/usr/bin/env python3
import sys
import csv
import argparse

def parse_args():
    # We can use argparse or custom parser.
    # Note: args can be anywhere before FILE or after?
    # Spec: Usage: csvq [--where COL=VALUE]... [--select COL,COL,...] [--sort COL [--numeric] [--desc]] FILE
    # Let's inspect argparse behavior.
    parser = argparse.ArgumentParser(prog='csvq', add_help=False)
    parser.add_argument('--where', action='append', default=[], help='Filter rows COL=VALUE')
    parser.add_argument('--select', default=None, help='Select columns COL,COL,...')
    parser.add_argument('--sort', default=None, help='Sort column')
    parser.add_argument('--numeric', action='store_true', default=False, help='Sort numerically')
    parser.add_argument('--desc', action='store_true', default=False, help='Sort descending')
    parser.add_argument('file', help='CSV file')
    return parser.parse_args()

def try_float(val):
    try:
        # Check if valid float (supports ints, floats, scientific notation etc.)
        # Note: strip or raw? In CSV, strings might have spaces or not. float(" 123 ") works.
        # But wait: does float("nan") or float("inf") count?
        # Usually float(val) works. What about empty string? float("") raises ValueError.
        # Wait, if val is empty or not a number, ValueError is raised.
        return float(val)
    except (ValueError, TypeError):
        return None

