            sys.stderr.write(f"csvq: unknown column: {col}\n")
            sys.exit(2)

    if selected_cols is not None:
        for col in selected_cols:
            if col not in col_to_idx:
                sys.stderr.write(f"csvq: unknown column: {col}\n")
                sys.exit(2)

