            valid_rows.sort(key=lambda x: x[0], reverse=args.desc)
            filtered_rows = [r for _, r in valid_rows] + invalid_rows
        else:
            filtered_rows.sort(key=lambda r: r[sort_idx] if sort_idx < len(r) else "", reverse=args.desc)

    # Project columns (--select)
    out_cols = selected_cols if selected_cols is not None else header
    out_indices = [col_to_idx[c] for c in out_cols]

    # Output CSV
    # csv.writer with lineterminator='\n', quoting=csv.QUOTE_MINIMAL
    writer = csv.writer(sys.stdout, lineterminator='\n', quoting=csv.QUOTE_MINIMAL)
    writer.writerow(out_cols)
